public class Solution {
    static class ChainMap {
        private static class Node {
            final int key; int value; Node next;
            Node(int key, int value, Node next) { this.key = key; this.value = value; this.next = next; }
        }

        private final Node[] buckets = new Node[4];
        private int size;

        private int index(int key) { return Math.floorMod(key, buckets.length); }

        void put(int key, int value) {
            int i = index(key);
            for (Node n = buckets[i]; n != null; n = n.next) {
                if (n.key == key) { n.value = value; return; }
            }
            buckets[i] = new Node(key, value, buckets[i]);
            size++;
        }

        Integer get(int key) {
            for (Node n = buckets[index(key)]; n != null; n = n.next) if (n.key == key) return n.value;
            return null;
        }

        // Percorre com o anterior: cabeça troca o bucket; meio/fim religa anterior.next.
        Integer remove(int key) {
            int i = index(key);
            Node anterior = null;
            for (Node n = buckets[i]; n != null; anterior = n, n = n.next) {
                if (n.key == key) {
                    if (anterior == null) buckets[i] = n.next;
                    else anterior.next = n.next;
                    size--;
                    return n.value;
                }
            }
            return null;
        }

        int size() { return size; }
    }
}

