import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    // Com 4 buckets, 1, 5, 9 e 13 caem todos no bucket 1. put insere na cabeça: cadeia 13 → 9 → 5 → 1.
    private static Solution.ChainMap cadeia() {
        var m = new Solution.ChainMap();
        for (int k : new int[]{1, 5, 9, 13}) m.put(k, k * 10);
        return m;
    }

    @Test void removeCabeca() {
        var m = cadeia();
        assertEquals(130, m.remove(13));
        assertNull(m.get(13));
        assertEquals(90, m.get(9));
        assertEquals(3, m.size());
    }

    @Test void removeMeioEFim() {
        var m = cadeia();
        assertEquals(50, m.remove(5));
        assertEquals(10, m.remove(1));
        assertEquals(130, m.get(13));
        assertEquals(90, m.get(9));
        assertEquals(2, m.size());
    }

    @Test void ausenteEDuasVezes() {
        var m = cadeia();
        assertNull(m.remove(2));
        assertEquals(90, m.remove(9));
        assertNull(m.remove(9));
        assertEquals(3, m.size());
    }

    @Test void negativos() {
        var m = new Solution.ChainMap();
        m.put(-3, 1);
        m.put(1, 2);
        assertEquals(1, m.remove(-3));
        assertEquals(2, m.get(1));
    }
}
